  --spacing: 0.25rem;
  --text-sm: 0.875rem;
}
.a {
  margin: 0;
  padding: var(--spacing);
  gap: calc(var(--spacing) * 2);
  top: calc(var(--spacing) * -1);
}
.inset-1 {
  inset: var(--spacing);
}
.-m-1 {
  margin: calc(var(--spacing) * -1);
}
.m-0 {
  margin: 0;
}
.m-1 {
  margin: var(--spacing);
}
.m-2 {
  margin: calc(var(--spacing) * 2);
}
.size-0 {
  width: 0;
  height: 0;
}
.text-sm\/1 {
  font-size: var(--text-sm);
  line-height: var(--spacing);
}
.text-sm\/6 {
  font-size: var(--text-sm);
  line-height: calc(var(--spacing) * 6);
}

