@layer properties;
:root, :host {
  --color-red-500: #f00;
}
.zoom-50 {
  zoom: 50%;
}
.zoom-\[1\.5\] {
  zoom: 1.5;
}
.scrollbar-auto {
  scrollbar-width: auto;
}
.scrollbar-none {
  scrollbar-width: none;
}
.scrollbar-thin {
  scrollbar-width: thin;
}
.scrollbar-thumb-red-500 {
  --tw-scrollbar-thumb: var(--color-red-500);
  scrollbar-color: var(--tw-scrollbar-thumb) var(--tw-scrollbar-track);
}
.scrollbar-track-red-500\/50 {
  --tw-scrollbar-track: color-mix(in srgb, #f00 50%, transparent);
  @supports (color: color-mix(in lab, red, red)) {
    --tw-scrollbar-track: color-mix(in oklab, var(--color-red-500) 50%, transparent);
  }
  scrollbar-color: var(--tw-scrollbar-thumb) var(--tw-scrollbar-track);
}
.scrollbar-gutter-both {
  scrollbar-gutter: stable both-edges;
}
.scrollbar-gutter-stable {
  scrollbar-gutter: stable;
}
.scroll-smooth {
  scroll-behavior: smooth;
}
.tab-4 {
  tab-size: 4;
}
.tab-\[13\] {
  tab-size: 13;
}
@property --tw-scrollbar-thumb {
  syntax: "<color>";
  inherits: false;
  initial-value: #0000;
}
@property --tw-scrollbar-track {
  syntax: "<color>";
  inherits: false;
  initial-value: #0000;
}
@layer properties {
  @supports ((-webkit-hyphens: none) and (not (margin-trim: inline))) or ((-moz-orient: inline) and (not (color:rgb(from red r g b)))) {
    *, ::before, ::after, ::backdrop {
      --tw-scrollbar-thumb: #0000;
      --tw-scrollbar-track: #0000;
    }
  }
}

